// แยกอีเมลขาเข้าตาม Flow 2 (แผนภาพ Auto mail flowchart):
//   ส่งต่อบริษัทประกัน = ผู้ส่งอยู่ใน Master_Data และ (เป็น Reply ของอีเมลที่ระบบส่ง หรือ หัวข้อมี prefix ตาม config: subject_prefixes)
//     - ถ้าปิด Auto Forward = Pending (รอเจ้าหน้าที่ส่งต่อ), ถ้ายังไม่ตั้ง insurance_email = Failed
//   นอกนั้นทั้งหมด = Needs Review (ผู้ส่งไม่อยู่ใน Master_Data, หรืออยู่แต่ไม่ใช่ Reply และหัวข้อไม่มี prefix)
//   ข้าม: ผู้ส่งอยู่ในรายการละเว้น / เป็นบริษัทประกัน / เมลที่ Message-ID อยู่ใน Email_Logs แล้ว
const cfg = $('Global Config').first().json;
const csv = s => String(s || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);
const clean = s => String(s || '').replace(/[<>]/g, '').trim();
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));

// --- config sheet (Category = SYSTEM) ---
const sys = {};
for (const i of $('Read config').all()) {
  const r = i.json;
  if (String(r.Category || '').trim().toUpperCase() === 'SYSTEM') sys[String(r.Key || '').trim()] = String(r.Value || '').trim();
}
const insuranceEmail = sys.insurance_email || '';
const autoForward = String(sys.auto_forward || 'TRUE').trim().toUpperCase() !== 'FALSE';
const prefixes = csv(sys.subject_prefixes);
const folderId = sys.attachment_folder_id || ''; // โฟลเดอร์ Google Drive เก็บไฟล์แนบ (ว่าง = ไม่เก็บ)
const testTo = String(cfg.test_forward_email || '').trim(); // ไม่ว่าง = โหมดทดสอบ forward ไปอีเมลนี้แทนบริษัทประกัน
const forwardTo = testTo || insuranceEmail;

const ignoreSenders = new Set(csv(cfg.ignore_senders));
if (insuranceEmail) ignoreSenders.add(insuranceEmail.toLowerCase());

// --- Master_Data / Email_Logs ---
const master = new Map();
for (const i of $('Read Master_Data').all()) {
  const e = String(i.json.Email || '').trim().toLowerCase();
  if (e) master.set(e, i.json);
}
const logged = new Set();
for (const i of $('Read Email_Logs').all()) {
  const id = clean(i.json.Message_ID);
  if (id) logged.add(id);
}

const results = [];
for (const item of $('Listener: IMAP Email Trigger').all()) {
  const mail = item.json;
  const from = mail.from?.value?.[0] || {};
  const addr = String(from.address || '').trim().toLowerCase();
  const subject = String(mail.subject || '').trim();
  const lowerSubject = subject.toLowerCase();
  const messageId = clean(mail.messageId || mail.headers?.['message-id']);

  // Reply ของอีเมลที่ระบบเคยส่ง: In-Reply-To / References ตรงกับ Message_ID ใน Email_Logs
  const refs = [].concat(mail.inReplyTo || mail.headers?.['in-reply-to'] || [], mail.references || mail.headers?.references || [])
    .join(' ').split(/\s+/).map(clean).filter(Boolean);
  const isReply = refs.some(r => logged.has(r));
  const matchedPrefix = prefixes.find(p => lowerSubject.includes(p));

  // route: ignore | forward | review | hold   (hold = ผ่านเงื่อนไขส่งต่อ แต่ส่งต่อไม่ได้ในตอนนี้)
  let route = 'ignore';
  let reason = '';
  let logStatus = '';
  const row = master.get(addr);

  if (!addr) reason = 'ไม่มีอีเมลผู้ส่ง';
  else if (ignoreSenders.has(addr)) reason = 'ผู้ส่งอยู่ในรายการละเว้น';
  else if (messageId && logged.has(messageId)) reason = 'ประมวลผลแล้ว';
  else if (!row) {
    route = 'review'; logStatus = 'Needs Review';
    reason = isReply ? 'ตอบกลับอีเมลที่ระบบส่ง แต่ไม่พบอีเมลผู้ส่งใน Master Data' : 'ไม่พบอีเมลผู้ส่งใน Master Data';
  } else if (!isReply && !matchedPrefix) {
    route = 'review'; logStatus = 'Needs Review';
    reason = prefixes.length
      ? 'ผู้ส่งอยู่ใน Master Data แต่ไม่ใช่การตอบกลับ และหัวข้อไม่มี prefix ที่กำหนด'
      : 'ผู้ส่งอยู่ใน Master Data แต่ยังไม่ได้ตั้งค่า prefix หัวข้อ (config: subject_prefixes)';
  } else {
    const via = isReply ? 'ตอบกลับอีเมลที่ระบบส่ง' : `หัวข้อมี prefix "${matchedPrefix}"`;
    if (!autoForward) { route = 'hold'; logStatus = 'Pending'; reason = `${via} แต่ปิด Auto Forward รอเจ้าหน้าที่ส่งต่อ`; }
    else if (!forwardTo) { route = 'hold'; logStatus = 'Failed'; reason = 'ยังไม่ได้ตั้งค่าอีเมลบริษัทประกัน (config: insurance_email)'; }
    else { route = 'forward'; reason = `พบผู้ส่งใน Master Data และ${via}`; }
  }
  if (route === 'ignore') continue;

  const binary = item.binary || {};
  const attachNames = Object.keys(binary);
  const bodyHtml = mail.html || `<pre style="white-space: pre-wrap; font-family: inherit;">${esc(mail.text || '(ไม่มีข้อความ)')}</pre>`;
  const customer = row
    ? `<p style="margin: 2px 0;"><strong>ลูกค้า:</strong> ${esc(row.Customer_Name)} (${esc(row.Insurance_Type || '-')})</p>
       <p style="margin: 2px 0;"><strong>เลขที่กรมธรรม์:</strong> ${esc(row.Policy_No || '-')} &nbsp; <strong>วันหมดอายุ:</strong> ${esc(row.Expiry_Date || '-')}</p>
       ${row.Current_Insurer ? `<p style="margin: 2px 0;"><strong>บริษัทประกันปัจจุบัน:</strong> ${esc(row.Current_Insurer)}</p>` : ''}`
    : '';
  const forwardHtml = `
<div style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6; color: #222;">
  ${sys.insurance_name ? `<p>เรียน ${esc(sys.insurance_name)}</p>` : ''}
  <div style="background-color: #e8f0fe; border-left: 4px solid #1a73e8; padding: 12px 16px; margin-bottom: 16px;">
    <strong>[AutoMail] ส่งต่ออัตโนมัติ</strong>${testTo ? ' <span style="color:#b45309;">(โหมดทดสอบ)</span>' : ''}<br/>
    <span style="font-size: 12px;">${esc(reason)}</span>
  </div>
  <div style="background-color: #f8f9fa; border: 1px solid #ddd; padding: 12px 16px; margin-bottom: 16px; font-size: 13px;">
    ${customer}
    <p style="margin: 2px 0;"><strong>From:</strong> ${esc(mail.from?.text || addr)}</p>
    <p style="margin: 2px 0;"><strong>Date:</strong> ${esc(mail.date || '')}</p>
    <p style="margin: 2px 0;"><strong>Subject:</strong> ${esc(subject)}</p>
    ${attachNames.length ? `<p style="margin: 2px 0;"><strong>ไฟล์แนบ:</strong> ${attachNames.length} ไฟล์</p>` : ''}
  </div>
  <div>${bodyHtml}</div>
</div>`;

  results.push({
    json: {
      route,
      reason,
      log_status: logStatus,
      log_round: route === 'review' ? 'Needs Review (อีเมลขาเข้า)' : 'อีเมลขาเข้า (ยังไม่ได้ส่งต่อ)',
      test_mode: Boolean(testTo),
      from_email: addr,
      from_name: from.name || '',
      subject,
      message_id: messageId,
      customer_id: row?.ID || '',
      customer_name: row?.Customer_Name || from.name || addr,
      forward_to: forwardTo,
      forward_subject: (testTo ? '[TEST] ' : '') + (lowerSubject.startsWith('fwd:') ? subject : `Fwd: ${subject}`),
      forward_html: forwardHtml,
      attach_names: attachNames.join(', '),
      // รายการไฟล์แนบ (ลำดับ ชื่อ ชนิด ขนาด) เก็บลง Email_Logs ให้เว็บเปิดไฟล์จากกล่องจดหมายด้วย Message-ID ตามลำดับนี้
      attachments_meta: JSON.stringify(Object.values(binary).map((b, i) => ({ index: i, name: b.fileName || ('attachment_' + i), mimeType: b.mimeType || 'application/octet-stream', size: b.fileSize || '' }))),
      folder_id: folderId,
      log_id: `LOG-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      // เก็บเนื้อหาไว้ใน Email_Logs (คอลัมน์ Original_Body) เพื่อให้ปุ่ม Re-forward ส่งซ้ำได้ (จำกัดความยาวของเซลล์ Google Sheets)
      original_body: bodyHtml.slice(0, 40000),
      review_alert_email: String(sys.review_alert_email || '').split(',').map(s => s.trim()).filter(Boolean).join(', ')
    },
    binary
  });
}
return results;

// แยกไฟล์แนบของแต่ละอีเมลเป็น 1 item ต่อ 1 ไฟล์ เพื่ออัปโหลดเข้า Google Drive (โฟลเดอร์จาก config: attachment_folder_id)
// ถ้าไม่มีไฟล์ต้องเก็บเลย ส่ง item { skip: true } ตัวเดียว เพื่อให้ flow ไปต่อที่ Collect Attachments โดยไม่ผ่านการอัปโหลด
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.folder_id) continue;
  for (const [key, bin] of Object.entries(item.binary || {})) {
    const fileName = bin.fileName || key;
    out.push({
      json: {
        log_id: j.log_id,
        folder_id: j.folder_id,
        file_name: fileName,
        drive_name: `${j.log_id}_${fileName}`,
        mime_type: bin.mimeType || 'application/octet-stream',
        size: bin.fileSize || ''
      },
      binary: { data: bin }
    });
  }
}
return out.length ? out : [{ json: { skip: true } }];

// รวมผลอัปโหลดไฟล์แนบกลับเข้าอีเมลแต่ละฉบับ (ผูกด้วย log_id) แล้วส่งอีเมลต่อพร้อม binary เดิม (ใช้แนบตอน forward)
// attachments = JSON [{ id, name, mimeType, size }] เก็บลงคอลัมน์ Attachments ของ Email_Logs ให้เว็บแสดงตัวอย่างไฟล์ได้
const tryAll = name => { try { return $(name).all(); } catch (e) { return []; } }; // node ที่ไม่ได้ทำงานในรอบนี้
const splits = tryAll('Split Attachments');
const uploads = tryAll('Upload to Drive');

const saved = {};
const failed = {};
uploads.forEach((u, i) => {
  const s = splits[u.pairedItem?.item ?? i]?.json;
  if (!s || s.skip) return;
  if (u.json.id) (saved[s.log_id] ||= []).push({ id: u.json.id, name: s.file_name, mimeType: s.mime_type, size: s.size });
  else (failed[s.log_id] ||= []).push(s.file_name);
});

return $('Route Inbound Mail').all().map(r => {
  const j = r.json;
  let note = '';
  if (failed[j.log_id]) note = `บันทึกไฟล์แนบลง Google Drive ไม่สำเร็จ: ${failed[j.log_id].join(', ')}`;
  else if (!j.folder_id && j.attach_names) note = 'ไม่ได้บันทึกไฟล์แนบ: ยังไม่ได้ตั้งค่าโฟลเดอร์ (config: attachment_folder_id)';
  return {
    json: { ...j, attachments: JSON.stringify(saved[j.log_id] || []), attachment_note: note },
    binary: r.binary
  };
});

// Re-forward จากปุ่มบนเว็บ: เว็บส่ง { action: 're-forward', logId, ... } มาที่ webhook
// ปลายทางอ่านจาก config (insurance_email) เสมอ ไม่ใช้ค่าที่มากับ request เพื่อกัน webhook ถูกเรียกให้ส่งเมลไปที่อื่น
// (เว็บเป็นฝ่ายเพิ่มแถว log ของการ re-forward เอง workflow นี้จึงไม่เขียน Email_Logs ซ้ำ)
const cfg = $('Re-forward Config').first().json;
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const body = $('Webhook: Re-forward').first().json.body || {};

if (body.action !== 're-forward' || !body.logId) throw new Error('คำขอไม่ถูกต้อง: ต้องมี action = re-forward และ logId');

const sys = {};
for (const i of $('Read config (Re-forward)').all()) {
  const r = i.json;
  if (String(r.Category || '').trim().toUpperCase() === 'SYSTEM') sys[String(r.Key || '').trim()] = String(r.Value || '').trim();
}
const testTo = String(cfg.test_forward_email || '').trim();
const forwardTo = testTo || sys.insurance_email;
if (!forwardTo) throw new Error('ยังไม่ได้ตั้งค่าอีเมลบริษัทประกัน (config: insurance_email)');

const row = $('Read Email_Logs (Re-forward)').all().map(i => i.json).find(r => String(r.Log_ID || '').trim() === String(body.logId).trim());
if (!row) throw new Error(`ไม่พบรายการ ${body.logId} ใน Email_Logs`);

const original = String(row.Original_Body || '').trim();
const note = original
  ? ''
  : '<p style="color:#b45309;">รายการนี้ไม่มีเนื้อหาต้นฉบับเก็บไว้ในระบบ (ส่งก่อนเริ่มเก็บเนื้อหา) กรุณาดูต้นฉบับจากกล่องจดหมาย</p>';

const subject = String(row.Subject || '');
return [{
  json: {
    forward_to: forwardTo,
    forward_subject: (testTo ? '[TEST] ' : '') + (subject.toLowerCase().startsWith('fwd:') ? subject : `Fwd: ${subject}`),
    forward_html: `
<div style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6; color: #222;">
  ${sys.insurance_name ? `<p>เรียน ${esc(sys.insurance_name)}</p>` : ''}
  <div style="background-color: #e8f0fe; border-left: 4px solid #1a73e8; padding: 12px 16px; margin-bottom: 16px;">
    <strong>[AutoMail] ส่งต่ออีกครั้ง (Re-forward)</strong>${testTo ? ' <span style="color:#b45309;">(โหมดทดสอบ)</span>' : ''}
  </div>
  <div style="background-color: #f8f9fa; border: 1px solid #ddd; padding: 12px 16px; margin-bottom: 16px; font-size: 13px;">
    <p style="margin: 2px 0;"><strong>ลูกค้า:</strong> ${esc(row.Customer_Name)} (${esc(row.Recipient_Email)})</p>
    <p style="margin: 2px 0;"><strong>รับเมื่อ:</strong> ${esc(row.Sent_Timestamp)}</p>
    <p style="margin: 2px 0;"><strong>Subject:</strong> ${esc(subject)}</p>
    <p style="margin: 2px 0; color:#64748b;">ไฟล์แนบเดิมไม่ได้ถูกส่งซ้ำ</p>
  </div>
  ${note}
  <div>${original}</div>
</div>`
  }
}];
